import os
from pathlib import Path

import pytest


def read_note(name: str) -> str:
    """Return the UTF-8 text of the file `name` inside the `notes` directory.

    `notes` is resolved relative to the current working directory. `name` is
    untrusted and may contain subdirectories (e.g. "sub/b.txt").

    Returns "" if the file is missing, is not a regular file (e.g. a
    directory), cannot be read or decoded as UTF-8, or the name is invalid
    (empty, contains a NUL byte, etc.).

    No name, however written (absolute paths, "..", symlinks that point
    outside, etc.), may cause a file outside `notes` to be read; such names
    also return "".
    """
    if not name or "\x00" in name:
        return ""
    try:
        root = Path("notes").resolve()
        target = (root / name).resolve()
        if not target.is_relative_to(root):
            return ""
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError, RuntimeError):
        return ""


@pytest.fixture
def sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("alpha", encoding="utf-8")
    (notes / "sub" / "b.txt").write_text("beta", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("SECRET", encoding="utf-8")
    (tmp_path / "notes_evil").mkdir()
    (tmp_path / "notes_evil" / "x.txt").write_text("EVIL", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_top_level_file(sandbox: Path) -> None:
    assert read_note("a.txt") == "alpha"


def test_reads_subdirectory_file(sandbox: Path) -> None:
    assert read_note("sub/b.txt") == "beta"


def test_unicode_content(sandbox: Path) -> None:
    (sandbox / "notes" / "u.txt").write_text("héllo ✓", encoding="utf-8")
    assert read_note("u.txt") == "héllo ✓"


def test_empty_file(sandbox: Path) -> None:
    (sandbox / "notes" / "empty.txt").write_text("", encoding="utf-8")
    assert read_note("empty.txt") == ""


def test_missing_file(sandbox: Path) -> None:
    assert read_note("nope.txt") == ""
    assert read_note("sub/nope.txt") == ""
    assert read_note("nodir/nope.txt") == ""


def test_directory_is_not_a_file(sandbox: Path) -> None:
    assert read_note("sub") == ""
    assert read_note("") == ""
    assert read_note(".") == ""


def test_parent_traversal(sandbox: Path) -> None:
    assert read_note("../secret.txt") == ""
    assert read_note("sub/../../secret.txt") == ""
    assert read_note("../../secret.txt") == ""
    assert read_note("./../secret.txt") == ""


def test_traversal_to_sibling_with_shared_prefix(sandbox: Path) -> None:
    assert read_note("../notes_evil/x.txt") == ""


def test_absolute_path_outside(sandbox: Path) -> None:
    assert read_note(str(sandbox / "secret.txt")) == ""
    assert read_note("/etc/passwd") == ""


def test_backslash_traversal(sandbox: Path) -> None:
    assert read_note("..\\secret.txt") == ""


def test_nul_byte(sandbox: Path) -> None:
    assert read_note("a.txt\x00") == ""
    assert read_note("a.txt\x00../secret.txt") == ""
    assert read_note("\x00") == ""


def test_symlink_file_escaping(sandbox: Path) -> None:
    link = sandbox / "notes" / "link.txt"
    try:
        os.symlink(sandbox / "secret.txt", link)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unavailable")
    assert read_note("link.txt") == ""


def test_symlink_dir_escaping(sandbox: Path) -> None:
    link = sandbox / "notes" / "linkdir"
    try:
        os.symlink(sandbox, link, target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unavailable")
    assert read_note("linkdir/secret.txt") == ""


def test_symlink_inside_notes_is_ok(sandbox: Path) -> None:
    link = sandbox / "notes" / "inner.txt"
    try:
        os.symlink(sandbox / "notes" / "a.txt", link)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unavailable")
    assert read_note("inner.txt") == "alpha"


def test_undecodable_file(sandbox: Path) -> None:
    (sandbox / "notes" / "bin.dat").write_bytes(b"\xff\xfe\xfa")
    assert read_note("bin.dat") == ""


def test_unreadable_file(sandbox: Path) -> None:
    p = sandbox / "notes" / "locked.txt"
    p.write_text("hidden", encoding="utf-8")
    p.chmod(0)
    try:
        if os.access(p, os.R_OK):
            pytest.skip("permissions not enforced (e.g. running as root)")
        assert read_note("locked.txt") == ""
    finally:
        p.chmod(0o600)


def test_missing_notes_directory(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    assert read_note("a.txt") == ""

